export const Route = createFileRoute('/dashboard')({
  // 1단계: 인증 체크 (직렬, redirect 가능)
  beforeLoad: async ({ context, location }) => {
    if (!context.auth) {
      throw redirect({
        to: '/login',
        search: { redirect: location.href },  // 원래 URL 저장
      })
    }
    return { user: context.auth.user }  // loader에서도 사용 가능
  },

  // 2단계: 데이터 페칭 (병렬)
  loader: async ({ context }) => {
    // context.user가 타입째로 사용 가능
    return fetchDashboardData(context.user.id)
  },
})

