import { defer } from '@tanstack/react-router'

export const Route = createFileRoute('/posts/$postId')({
  loader: async ({ params }) => {
    // 빠른 데이터: await로 기다림 (렌더링 블로킹)
    const post = await fetchPost(params.postId)

    // 느린 데이터: promise를 그대로 넘김 (블로킹 안 함)
    const commentsPromise = fetchComments(params.postId)

    return {
      post,                        // 즉시 사용 가능
      commentsPromise: defer(commentsPromise),  // 나중에 채워짐
    }
  },
})

function PostPage() {
  const { post, commentsPromise } = Route.useLoaderData()

  return (
    <div>
      <h1>{post.title}</h1>  {/* 즉시 렌더링 */}

      {/* 느린 데이터: 준비될 때까지 fallback 표시 */}
      <Suspense fallback={<CommentsSkeleton />}>
        <Await promise={commentsPromise}>
          {(comments) => <CommentsList comments={comments} />}
        </Await>
      </Suspense>
    </div>
  )
}

