// 파일 구조
// routes/
//   dashboard.tsx          → 공통 레이아웃
//   dashboard/
//     index.tsx            → /dashboard
//     settings.tsx         → /dashboard/settings
//     _pathless.tsx        → URL 없는 레이아웃 (인증된 섹션)
//     _pathless/
//       profile.tsx        → /profile (URL에 _pathless 없음)

// dashboard.tsx — 레이아웃 컴포넌트
export const Route = createFileRoute('/dashboard')({
  component: DashboardLayout,
})

function DashboardLayout() {
  return (
    <div>
      <Sidebar />          {/* 모든 /dashboard/* 에서 공유 */}
      <main>
        <Outlet />         {/* 자식 라우트가 여기 렌더링 */}
      </main>
    </div>
  )
}

// Pathless Layout — URL에 영향 없이 레이아웃만 공유
// _authenticated.tsx
export const Route = createFileRoute('/_authenticated')({
  beforeLoad: ({ context }) => {
    if (!context.auth) throw redirect({ to: '/login' })
  },
  component: () => <Outlet />,  // 레이아웃 없이 인증만 체크
})

