// Next.js / React Router의 내장 <Form>
<Form method="post" action="/users">  // 서버 Action으로 자동 연결
  <input name="email" />
  <button type="submit">Submit</button>
</Form>

// TanStack Start: 내장 없음 → TanStack Form으로 대체
import { useForm } from '@tanstack/react-form'
import { zodValidator } from '@tanstack/zod-form-adapter'

const createUser = createServerFn({ method: 'POST' })
  .validator(zodValidator(UserSchema))
  .handler(async ({ data }) => db.users.create({ data }))

function UserForm() {
  const form = useForm({
    defaultValues: { email: '', name: '' },
    onSubmit: async ({ value }) => {
      await createUser({ data: value })  // 타입 안전 서버 호출
    },
  })

  return (
    <form onSubmit={(e) => { e.preventDefault(); form.handleSubmit() }}>
      <form.Field name="email" validators={{ onChange: zodValidator(z.string().email()) }}>
        {(field) => <input value={field.state.value} onChange={e => field.handleChange(e.target.value)} />}
      </form.Field>
      <button type="submit">Submit</button>
    </form>
  )
}

